import { gs, GlideRecord } from '@servicenow/glide'

export function getVisualCardsForCatalog() {
  try {
    const categoryId = getVisualCardsCategoryId()
    const cards = []

    const modelGr = new GlideRecord('cmdb_model')
    modelGr.addQuery('type', 'Product')
    modelGr.addQuery('status', 'In Production')

    if (categoryId) {
      // Handle both reference and string values
      const condition = modelGr.addQuery('cmdb_model_category', categoryId)
      condition.addOrCondition('cmdb_model_category', 'visual_cards_category')
    } else {
      // Fallback filter
      modelGr.addQuery('short_description', 'CONTAINS', 'card')
    }

    modelGr.query()

    while (modelGr.next()) {
      cards.push({
        sys_id: modelGr.getUniqueValue(),
        name: modelGr.getValue('name'),
        short_description: modelGr.getValue('short_description')
      })
    }

    return cards

  } catch (error) {
    gs.error('Error fetching visual cards for catalog: ' + error.message)
    return []
  }
}

export function getVisualCardsCategoryId() {
  try {
    const categoryGr = new GlideRecord('cmdb_model_category')
    categoryGr.addQuery('name', 'Visual Cards')
    categoryGr.query()

    if (categoryGr.next()) {
      return categoryGr.getUniqueValue()
    }
  } catch (error) {
    gs.warn('Could not find Visual Cards model category: ' + error.message)
  }

  return null
}

export function getAssignedUsersForCard(cardId) {
  try {
    const users = []
    const assetGr = new GlideRecord('alm_asset')
    assetGr.addQuery('model', cardId)
    assetGr.addQuery('install_status', 1) // Installed
    assetGr.query()

    while (assetGr.next()) {
      const userId = assetGr.getValue('assigned_to')
      if (userId) {
        users.push(userId)
      }
    }

    return users

  } catch (error) {
    gs.error('Error fetching assigned users for card: ' + error.message)
    return []
  }
}
